           STORAGE_LOG_MISALIGNED, STORAGE_LOG_STAGE_NONE, 0);
    assert(w.fd == -1);
    assert(read_file("f.log", after, sizeof after) == sizeof partial);
    assert(memcmp(after, partial, sizeof partial) == 0);

    remove_temp_file("f.log");
    remove_temp_dir();
}

