    make_temp_dir();
    file_path(missing, sizeof missing, "no-such-dir");
    expect(storage_log_open(&w, missing, "g.log", 0, 0),
           STORAGE_LOG_OS_ERROR, STORAGE_LOG_STAGE_OPEN_DIR, ENOENT);
