    fake_reset();
    fake_tail(4, 0);
    fake.pread_eintr_count = 2;
    expect_ok(open_fake(&w, 5));
    assert(fake.pread_calls == 3);
    assert(fake.pread_offset == 2 * STORAGE_RECORD_SIZE_BYTES);
    assert(w.file_size_bytes == 3 * STORAGE_RECORD_SIZE_BYTES);
